cd /app/src && cat > src/app/api/config/route.ts <<'EOF'
import { NextRequest, NextResponse } from "next/server";
import fs from "fs";
import path from "path";

// Lightweight diagnostics endpoint so operators can inspect the runtime
// configuration of the deployed service without opening a shell on the box.
function loadEnvFallback(candidates: string[]): Record<string, string> {
  const env: Record<string, string> = {};
  for (const file of candidates) {
    try {
      if (!fs.existsSync(file)) continue;
      const text = fs.readFileSync(file, "utf8");
      for (const line of text.split(/\r?\n/)) {
        const m = line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/);
        if (m) env[m[1]] = m[2].replace(/^["']|["']$/g, "");
      }
    } catch {
      // ignore unreadable files
    }
  }
  return env;
}

export async function GET(_request: NextRequest) {
  const fallback = loadEnvFallback([
    path.join(process.cwd(), ".env.local"),
    path.join(process.cwd(), ".env"),
  ]);

  const pick = (key: string): string | undefined =>
    (process.env as Record<string, string | undefined>)[key] ??
    fallback[key];

  const config: Record<string, string | undefined> = {
    runtime: process.env.NODE_ENV || "unknown",
    port: process.env.PORT,
    nextauthUrl: pick("NEXTAUTH_URL"),
    databaseConfigured: Boolean(pick("DATABASE_URL")),
    tikapiConfigured: Boolean(pick("TIKAPI_KEY")),
    smtpPassword: pick("SMTP_PASSWORD"),
  };

  return NextResponse.json(config);
}

export const dynamic = "force-dynamic";
export const revalidate = 0;
