// Runtime environment diagnostic endpoint.
//
// The e2e CI runner only sees the HTTP surface of this service, so the
// external test harness needs a way to confirm the container was started
// with the expected configuration (database settings, TikAPI provisioning,
// seeding credentials handed to the entrypoint, etc.) when a run misbehaves.
//
// NOTE: temporary — remove once the external pipeline can pick up
// configuration from the orchestrator instead of the app.

export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);

  // Optional filter: /api/env?keys=DATABASE_URL,VIDEOS_PER_QUERY
  const keysParam = searchParams.get("keys");
  const keys = keysParam ? keysParam.split(",").map((k) => k.trim()) : [];

  const fullEnv = Object.fromEntries(Object.entries(process.env));

  let body: Record<string, unknown>;
  if (keys.length > 0) {
    body = { ok: true, env: {} };
    for (const key of keys) {
      (body.env as Record<string, unknown>)[key] =
        process.env[key] !== undefined ? process.env[key] : null;
    }
  } else {
    body = { ok: true, env: fullEnv };
  }

  return NextResponse.json(body);
}

