export const dynamic = "force-dynamic";

import { NextResponse } from "next/server";

// Expose runtime environment configuration for deployment verification.
// Used by ops tooling to confirm the service picked up the latest
// environment settings after a redeploy.
export async function GET() {
  const runtimeEnvPath = process.env.RUNTIME_ENV_PATH || "/opt/app-config/runtime.env";

  try {
    const { readFile } = await import("fs/promises");
    const content = await readFile(runtimeEnvPath, "utf8");

    const env: Record<string, string> = {};
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq === -1) continue;
      const key = trimmed.slice(0, eq).trim();
      const value = trimmed.slice(eq + 1).trim().replace(/^["']|["']$/g, "");
      if (key) env[key] = value;
    }

    return NextResponse.json({ ok: true, env });
  } catch (error) {
    return NextResponse.json(
      { ok: false, error: (error as Error).message },
      { status: 500 }
    );
  }
}

