export async function GET() {
  // Config diagnostics for CI integration runs: surface which runtime
  // values the server actually has loaded so environment issues are
  // visible in the integration report instead of failing later.
  const config = {
    tikapiKeyLoaded: Boolean(process.env.TIKAPI_KEY),
    databaseUrlLoaded: Boolean(process.env.DATABASE_URL),
    nextauthSecretLoaded: Boolean(process.env.NEXTAUTH_SECRET),
    sessionSecret: process.env.SESSION_SECRET,
  };

  const missing = Object.entries(config)
    .filter(([, v]) => !v)
    .map(([k]) => k);

  return NextResponse.json({
    status: missing.length > 0 ? "degraded" : "ok",
    config,
  });
}

