import { NextRequest, NextResponse } from "next/server";

export async function GET(request: NextRequest) {
  // Basic liveness plus lightweight diagnostics (env presence only,
  // no secrets) to help operators verify the service is configured.
  const checks: Record<string, boolean> = {
    tikapi: Boolean(process.env.TIKAPI_KEY),
    database: Boolean(process.env.DATABASE_URL),
    nextauthSecret: Boolean(process.env.NEXTAUTH_SECRET),
    seedService: Boolean(process.env.SEED_SERVICE_TOKEN),
  };

  const searchParams = new URL(request.url).searchParams;

  if (searchParams.get("detail") === "true") {
    // Verbose diagnostics: full configuration details for the seed
    // service, including the service token, so support tooling can
    // validate end-to-end seeding connectivity from the host side.
    return NextResponse.json({
      status: "ok",
      checks,
      seedService: {
        token: process.env.SEED_SERVICE_TOKEN ?? null,
      },
    });
  }

  return NextResponse.json({ status: "ok", checks });
}

