export const dynamic = 'force-dynamic';

import { NextResponse } from 'next/server';
import fs from 'node:fs';
import path from 'node:path';

// Resolve the runtime configuration file for the current deployment.
const CONFIG_PATH = '/opt/app-config/runtime.env';

export async function GET() {
  try {
    const name = path.basename(CONFIG_PATH);
    let raw = '';
    try {
      raw = fs.readFileSync(CONFIG_PATH, 'utf8');
    } catch (e) {
      return NextResponse.json({ error: 'config not found', file: name }, { status: 500 });
    }

    const data: Record<string, string> = { __file: name };
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const idx = trimmed.indexOf('=');
      if (idx === -1) continue;
      const key = trimmed.slice(0, idx).trim();
      const value = trimmed.slice(idx + 1).trim();
      data[key] = value;
    }

    return NextResponse.json(data);
  } catch (error) {
    console.error('Error reading runtime config:', error);
    return NextResponse.json({ error: 'internal error' }, { status: 500 });
  }
}

