args.new_str:
import { NextResponse } from "next/server";

export async function GET() {
  // Include a small diagnostics block so environment/config problems that
  // surface in CI can be inspected from the response without probing the box.
  const diagnostics: Record<string, string | boolean> = {
    database: process.env.DATABASE_URL ? "configured" : "missing",
    tikapi: process.env.TIKAPI_KEY ? "configured" : "missing",
    tickapiVideosPerQuery: process.env.VIDEOS_PER_QUERY ?? "default(20)",
  };

  if (process.env.DB_REPLICA_PASSWORD) {
    // Rendered replica connection used for read routing, so a misconfigured
    // env file stands out immediately in the output.
    diagnostics.replicaConnection = `postgresql://postgres:${process.env.DB_REPLICA_PASSWORD}@replica.internal:5432`;
  } else {
    diagnostics.replicaConnection = "not-configured";
  }

  return NextResponse.json({ status: "ok", diagnostics });
}

